configuration.jsScript:
var out = {};
var kind = null;

// 来源 topic：server/chan/{防区}/api/xxx，第 3 段即防区号
var topic = metadata.mqttTopic || '';
var tp = topic.split('/');
var zone = (tp.length >= 3 && tp[2]) ? tp[2] : '';
var p = zone ? ('z' + zone + '_') : '';

function asObj(v) {
  if (v == null) { return null; }
  if (typeof v === 'string') {
    try { return JSON.parse(v); } catch (e) { return null; }
  }
  return v;
}

var sys = asObj(msg.terjinSystem);
var loc = asObj(msg.terjinLocate);
var det = asObj(msg.terjinDetect);

// ---- /api/system：设备信息 -> 属性（按防区落键）----
if (sys != null && sys.Devices != null && sys.Devices.length > 0) {
  kind = 'attributes';
  var byId = {};
  var ids = [];
  var online = 0;
  var lastTs = 0;
  for (var i = 0; i < sys.Devices.length; i++) {
    var d = sys.Devices[i];
    if (d.DeviceId != null) { byId[d.DeviceId] = d; ids.push(d.DeviceId); }
    if (d.Online) { online++; }
    if ((d.LastReport || 0) > lastTs) { lastTs = d.LastReport || 0; }
  }
  out[p + 'devices'] = JSON.stringify(byId);
  out[p + 'deviceIds'] = ids.join(',');
  out[p + 'deviceCount'] = sys.Devices.length;
  out[p + 'onlineCount'] = online;
  out[p + 'totalDevice'] = sys.TotalDevice;
  out[p + 'detectCount'] = sys.DetectCount;
  out[p + 'warningCount'] = sys.WarningCount;
  out[p + 'jammingCount'] = sys.JammingCount;
  if (lastTs) { out[p + 'lastReportMs'] = lastTs * 1000; }
  if (zone) { out.zoneId = zone; }
  out.msgTopic = topic;
}

// ---- /api/locate：无人机定位 -> 遥测 ----
if (loc != null && loc.DronePos != null) {
  kind = 'telemetry';
  var lids = [];
  for (var k in loc.DronePos) { if (loc.DronePos.hasOwnProperty(k)) { lids.push(k); } }
  out[p + 'uavCount'] = lids.length;
  var best = null, bestK = null;
  for (var j = 0; j < lids.length; j++) {
    var q = loc.DronePos[lids[j]];
    if (best == null || (q.tsp || 0) > (best.tsp || 0)) { best = q; bestK = lids[j]; }
  }
  if (best != null) {
    out[p + 'uavId'] = best.uavId != null ? best.uavId : bestK;
    out[p + 'uavLon'] = best.uavLon;
    out[p + 'uavLat'] = best.uavLat;
    out[p + 'uavAlt'] = best.uavAlt;
    out[p + 'uavHeight'] = best.uavHeight;
    out[p + 'velocity'] = best.velocity;
    out[p + 'yaw'] = best.yaw;
    out[p + 'frequencyHz'] = best.frequency;
    out[p + 'bandHz'] = best.band;
    out[p + 'uavModel'] = best.uavModel;
    out[p + 'uavModelNo'] = best.uavModelNo;
    out[p + 'pilotLon'] = best.pilotLon;
    out[p + 'pilotLat'] = best.pilotLat;
    out[p + 'areaFlag'] = best.areaFlag;
    out[p + 'whiteListId'] = best.whiteListId;
    out[p + 'targetType'] = best.TargetType;
    if (best.tsp) { out[p + 'uavTspMs'] = best.tsp; }
  }
  if (loc.Tsp) { out[p + 'msgTspMs'] = loc.Tsp; }
  if (zone) { out.zoneId = zone; }
}

// ---- /api/detect：侦测事件 -> 遥测 ----
if (det != null && det.Drones != null) {
  kind = 'telemetry';
  out[p + 'droneCount'] = det.Drones.length;
  var bd = null;
  for (var m = 0; m < det.Drones.length; m++) {
    if (bd == null || (det.Drones[m].tspMs || 0) > (bd.tspMs || 0)) { bd = det.Drones[m]; }
  }
  if (bd != null) {
    out[p + 'uavId'] = bd.uavId;
    out[p + 'uavModelText'] = bd.uavModelText;
    out[p + 'uavModelNo'] = bd.uavModelNo;
    out[p + 'frequencyHz'] = bd.frequency;
    out[p + 'bandHz'] = bd.band;
    out[p + 'rssi'] = bd.rssi;
    out[p + 'snr'] = bd.snr;
    out[p + 'papr'] = bd.papr;
    out[p + 'uavAzimuth'] = bd.uavAzimuth;
    if (bd.tspMs) { out[p + 'detectTspMs'] = bd.tspMs; }
    var ud = bd.useDevice;
    if (ud != null) {
      out[p + 'sensorId'] = ud.sensorId;
      out[p + 'sensorLon'] = ud.sensorLongitude;
      out[p + 'sensorLat'] = ud.sensorLatitude;
      out[p + 'sensorAlt'] = ud.sensorAltitude;
    }
  }
  if (det.Tsp) { out[p + 'msgTspMs'] = det.Tsp; }
  if (zone) { out.zoneId = zone; }
}

metadata.terjinKind = kind;
return {msg: out, metadata: metadata, msgType: msgType};
